fn main() {
    let mut v = vec![1, 2, 3];

    // Option A: copy the value out (i32 is Copy) so no borrow
    // of the buffer is held across the mutation.
    let first = v[0];
    v.push(4);
    println!("{first} and len {}", v.len());

    // Option B: scope the borrow so it ends before the mutation.
    let second = {
        let r = &v[1];
        *r
    };
    v.push(5);
    println!("second: {second}");

    // Option C (the production pattern): use indices instead of
    // references when a collection may grow while you hold a view.
    let idx = 0;
    v.push(6);
    println!("v[{idx}] = {}", v[idx]);
}
